using System;using System.Linq;using System.Drawing;using System.Reflection;using System.Threading;using System.Windows.Forms;using System.IO;using System.Collections.Generic;
namespace Frociart.Tests {
static class SizingTests {
 static BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;static int checks;
 static void Check(bool b,string s){if(!b)throw new Exception(s);checks++;Console.WriteLine("PASS "+s);}
 static object Get(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}
 static object Call(object o,string n,params object[] a){return o.GetType().GetMethods(F).First(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(o,a);}
 static void Pump(int ms){var t=DateTime.UtcNow.AddMilliseconds(ms);do{Application.DoEvents();Thread.Sleep(2);}while(DateTime.UtcNow<t);}
 static void SetText(FlowNode n,string text){n.Text=text;if(n.Kind==NodeKind.Pause){n.Breakpoint=true;n.BreakpointCondition=text;}}
 static string Long="totale_complessivo_delle_operazioni = quantita_disponibile * prezzo_unitario";
 static string Multi=String.Join("\n",Enumerable.Range(1,12).Select(i=>"valore_"+i+" = "+i+" + 25"));
 [STAThread]static void Main(){Application.EnableVisualStyles();UiMotion.SetEnabled(true);string folder=Environment.GetEnvironmentVariable("REVIEW_OUTPUT");Directory.CreateDirectory(folder);
 foreach(NodeKind kind in Enum.GetValues(typeof(NodeKind))){var n=new FlowNode{Kind=kind,Text="x",Id="node",X=0,Y=0};SizeF min=FlowSizing.Default(kind);Check(FlowSizing.Size(n)==min,kind+" starts at its default size");SetText(n,Long);var wide=FlowSizing.Size(n);Check(wide.Width>min.Width&&wide.Width<621,kind+" grows horizontally within readable width");SetText(n,Multi);var tall=FlowSizing.Size(n);Check(tall.Height>min.Height,kind+" grows for all twelve lines");
  using(var bmp=new Bitmap(1,1))using(var g=Graphics.FromImage(bmp))using(var font=new Font("Segoe UI",kind==NodeKind.Decision?14:15.333f,kind==NodeKind.Start||kind==NodeKind.End?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel)){
   var b=FlowCanvas.GetNodeBounds(n);var body=kind==NodeKind.Decision?FlowSizing.DecisionBody(b):new RectangleF(b.X,b.Y,kind==NodeKind.Start||kind==NodeKind.End?b.Width-64:b.Width-(kind==NodeKind.Input||kind==NodeKind.Output?60:36),b.Height-(kind==NodeKind.Start||kind==NodeKind.End?20:43));using(var f=new StringFormat()){f.FormatFlags=StringFormatFlags.LineLimit;var required=g.MeasureString(FlowSizing.Text(n),font,new SizeF(body.Width,100000),f);Check(required.Height<=body.Height,kind+" entire body fits its content rectangle");}
   if(kind==NodeKind.Decision){var r=FlowSizing.DecisionBody(b);Check(Math.Abs(r.Right-b.Width/2)/(b.Width/2)+Math.Abs(r.Bottom-b.Height/2)/(b.Height/2)<=1, "Decision body fits inside diamond corners");}
  }
  using(var c=new FlowCanvas{Size=new Size(900,700),Diagram=new Diagram()}){c.Diagram.Nodes.Add(n);using(var image=c.RenderExportBitmap(.8f))image.Save(Path.Combine(folder,"sizing-"+kind+".png"));}
  SetText(n,"x");Check(FlowSizing.Size(n)==min,kind+" shrinks back without going below default");SetText(n,new string('W',8192));var maximum=FlowSizing.Size(n);Check(maximum.Width<=620&&maximum.Height>0&&!float.IsInfinity(maximum.Height),kind+" handles the full text limit");SetText(n,"Caffè 👩‍💻 漢字\n\nultima riga");Check(FlowSizing.Size(n).Height>=min.Height,kind+" handles unicode and blank lines");
 }
 using(var f=new Form{ClientSize=new Size(1200,750)})using(var c=new FlowCanvas{Dock=DockStyle.Fill,Diagram=new Diagram()}){var n=new FlowNode{Id="a",Kind=NodeKind.Process,Text="x=0",X=150,Y=200};c.Diagram.Nodes.Add(n);f.Controls.Add(c);f.Show();Pump(100);var before=(RectangleF)Call(c,"DisplayBounds",n);c.PreviewText("a",Long);Pump(65);var during=(RectangleF)Call(c,"DisplayBounds",n);var final=FlowCanvas.GetNodeBounds(n);Console.WriteLine("ANIMATION before="+before+" during="+during+" final="+final+" enabled="+UiMotion.Enabled);Check(!UiMotion.Enabled||during.Width>before.Width&&during.Width<=final.Width+(final.Width-before.Width)*.06f,"Live outline follows the bounded spring, including its intended overshoot");Check(n.Text=="x=0"&&DiagramIO.Clone(c.Diagram).Nodes[0].Text=="x=0"&&DiagramIO.Clone(c.Diagram).Nodes[0].PreviewText==null,"Preview does not change committed text or serialized data");Pump(500);var settled=(RectangleF)Call(c,"DisplayBounds",n);Check(Math.Abs(settled.Width-final.Width)<.1,"Size settles exactly");Check(!(bool)Get(c,"_exportRendering"),"Export state is restored");Check(!((System.Windows.Forms.Timer)Get(c,"manipulationTimer")).Enabled,"Sizing repaint timer stops at rest");c.PreviewText("a",Multi);Pump(50);c.PreviewText("a","x");Pump(500);Check(((RectangleF)Call(c,"DisplayBounds",n)).Size==FlowSizing.Default(n.Kind),"Interrupted typing and deletion settle to latest size");f.Close();}
 using(var main=new MainForm(null,true)){main.Show();Pump(100);var d=new Diagram();d.Nodes.AddRange(new[]{new FlowNode{Id="a",Kind=NodeKind.Process,Text="x=0",X=200,Y=200},new FlowNode{Id="b",Kind=NodeKind.End,Text="Fine",X=200,Y=400},new FlowNode{Id="far",Kind=NodeKind.Process,Text="x=1",X=2000,Y=100}});d.Edges.Add(new FlowEdge{Id="edge",From="a",To="b"});main.SetDocument(d,null,false);main.Canvas.SelectNode("a");var edit=(TextBox)Get(main,"expression");edit.Text=Multi;Pump(80);Check(d.Nodes[0].Text=="x=0"&&FlowSizing.Size(d.Nodes[0]).Height>88,"Real desktop inspector previews while preserving its draft");main.CommitInspector();Pump(500);Check(d.Nodes[0].Text==Multi&&d.Nodes[0].PreviewText==null,"Apply commits text and removes preview");Check(!FlowCanvas.GetNodeBounds(d.Nodes[0]).IntersectsWith(FlowCanvas.GetNodeBounds(d.Nodes[1])),"Local reflow removes overlap after growth");Check(d.Nodes[1].Y>=FlowCanvas.GetNodeBounds(d.Nodes[0]).Bottom+18,"Growing a block keeps its continuation below it");Check(d.Nodes[2].X==2000&&d.Nodes[2].Y==100,"Unrelated region stays exactly fixed");Check(d.Edges.Count==1&&d.Edges[0].Id=="edge"&&d.Edges[0].To=="b","Resizing preserves graph connections");Call(main,"Undo");Check(main.Document.Nodes[0].Text=="x=0"&&main.Document.Nodes[1].Y==400,"One Undo restores text and local placement");main.SetDocument(new Diagram(),null,false);main.Close();}
 Console.WriteLine("SIZING PASS checks="+checks);
 }
}
}
